#[capability(
    module = "zendesk",
    id = "update-ticket",
    display_name = r##"Update Ticket"##,
    side_effects = true
)]
pub async fn update_ticket(input: UpdateTicketInput) -> Result<TicketUpdateResponse, AgentError> {
    let connection = kit::require_connection(&input._connection, "ZENDESK")?;
    input.request()?.send(connection, "ZENDESK").await
}

impl UpdateTicketInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = format!(
            "/api/v2/tickets/{ticket_id}",
            ticket_id = kit::encode_path(&self.ticket_id)
        );
        let request = kit::Request::new("PUT", path);
        request.json_body(
            kit::Body::new()
                .field_opt("additional_collaborators", &self.additional_collaborators)
                .field_opt("assignee_email", &self.assignee_email)
                .field_opt("assignee_id", &self.assignee_id)
                .field_opt("attribute_value_ids", &self.attribute_value_ids)
                .field_opt("brand_id", &self.brand_id)
                .field_opt("collaborator_ids", &self.collaborator_ids)
                .field_opt("collaborators", &self.collaborators)
                .field_opt("comment", &self.comment)
                .field_opt("custom_fields", &self.custom_fields)
                .field_opt("custom_status_id", &self.custom_status_id)
                .field_opt("description", &self.description)
                .field_opt("due_at", &self.due_at)
                .field_opt("email_ccs", &self.email_ccs)
                .field_opt("external_id", &self.external_id)
                .field_opt("fields", &self.fields)
                .field_opt("followers", &self.followers)
                .field_opt("forum_topic_id", &self.forum_topic_id)
                .field_opt("group_id", &self.group_id)
                .field_opt("macro_id", &self.macro_id)
                .field_opt("macro_ids", &self.macro_ids)
                .field_opt("metadata", &self.metadata)
                .field_opt("organization_id", &self.organization_id)
                .field_opt("origin_zrn", &self.origin_zrn)
                .field_opt("priority", &self.priority)
                .field_opt("problem_id", &self.problem_id)
                .field_opt("raw_subject", &self.raw_subject)
                .field_opt("recipient", &self.recipient)
                .field_opt("requester", &self.requester)
                .field_opt("requester_id", &self.requester_id)
                .field_opt("safe_update", &self.safe_update)
                .field_opt("sharing_agreement_ids", &self.sharing_agreement_ids)
                .field_opt("sharing_agreements", &self.sharing_agreements)
                .field_opt("status", &self.status)
                .field_opt("subject", &self.subject)
                .field_opt("submitter_id", &self.submitter_id)
                .field_opt("support_type", &self.support_type)
                .field_opt("suspended_ticket_id", &self.suspended_ticket_id)
                .field_opt("suspension_type_id", &self.suspension_type_id)
                .field_opt("system_metadata", &self.system_metadata)
                .field_opt("tags", &self.tags)
                .field_opt("tde_workspace", &self.tde_workspace)
                .field_opt("ticket_form_id", &self.ticket_form_id)
                .field_opt("tpe_voice_comment", &self.tpe_voice_comment)
                .field_opt("type", &self.r#type)
                .field_opt("updated_stamp", &self.updated_stamp)
                .field_opt("via", &self.via)
                .field_opt("via_followup_source_id", &self.via_followup_source_id)
                .field_opt("via_id", &self.via_id)
                .field_opt("voice_comment", &self.voice_comment)
                .envelope("ticket"),
            "ZENDESK",
        )
    }
}

